4. Returns a new Location containing the selected coordinates. / 返回正确坐标对象。
Part (b): sumPath (5 points)
1. Includes the starting value. / 包含起点。
2. Continues until both coordinates identify the bottom-right cell. / 直到右下角才停止。
3. Uses getNextLoc to obtain each next location. / 调用指定辅助方法。
4. Updates both coordinates and accumulates each visited value exactly once. / 更新两个坐标且每格只加一次。
5. Includes the final cell and returns the sum. / 包含终点并返回和。

questions.reference_solution:
public Location getNextLoc(int row, int col) {
    if (row == grid.length - 1) { return new Location(row, col + 1); }
    if (col == grid[0].length - 1) { return new Location(row + 1, col); }
    if (grid[row + 1][col] < grid[row][col + 1]) { return new Location(row + 1, col); }
    return new Location(row, col + 1);
}
public int sumPath(int row, int col) {
    int sum = grid[row][col];
    while (row != grid.length - 1 || col != grid[0].length - 1) {
        Location next = getNextLoc(row, col);
        row = next.getRow();
        col = next.getCol();
        sum += grid[row][col];
    }
    return sum;
}

