questions.answer:
Reference answer / 参考答案（非官方原版）
Keeping a null candidate correctly handles crops that do not occur, and does not assume yields are positive. sameCrop compares one column, not entire rows.

public Plot getHighestYield(String c) {
    Plot best = null;
    for (Plot[] row : farmPlots) {
        for (Plot plot : row) {
            if (plot.getCropType().equals(c) && (best == null || plot.getCropYield() > best.getCropYield())) {
                best = plot;
            }
        }
    }
    return best;
}
public boolean sameCrop(int col) {
    String crop = farmPlots[0][col].getCropType();
    for (int r = 1; r < farmPlots.length; r++) {
        if (!farmPlots[r][col].getCropType().equals(crop)) { return false; }
    }
    return true;
}

